//! Regenerates Telegram's visible push catalog from https://core.telegram.org/api/config.json: the relay's
//! allowlist in `src/web_push/catalog.rs` and the iOS English strings. A new key needs human review before the
//! regenerated files are committed.

use std::cmp::Ordering;
use std::path::Path;

use bettertg_backend::security::sha256_hex;
use serde_json::Value;

const SOURCE_URL: &str = "https://core.telegram.org/api/config.json";
const SERVICE_OR_UNSUPPORTED_KEYS: &[&str] = &["DC_UPDATE", "PHONE_CALL_REQUEST"];

/// ICU's root collation for `[A-Z0-9_]` keys, which `localeCompare` sorted them by: `_` before digits before letters.
fn collation_weight(byte: u8) -> u8 {
    match byte {
        b'_' => 0,
        b'0'..=b'9' => 1 + byte - b'0',
        _ => 11 + byte.to_ascii_uppercase().saturating_sub(b'A'),
    }
}

fn collate(left: &str, right: &str) -> Ordering {
    left.bytes().map(collation_weight).cmp(right.bytes().map(collation_weight))
}

/// Telegram's `{1}` placeholders as Apple's `%1$@`, with literal percent signs escaped.
fn apple_format(template: &str) -> String {
    let escaped = template.replace('%', "%%");
    let mut output = String::with_capacity(escaped.len());
    let mut rest = escaped.as_str();
    while let Some(start) = rest.find('{') {
        output.push_str(&rest[..start]);
        let after = &rest[start + 1..];
        match after.find('}') {
            Some(end) if end > 0 && after[..end].bytes().all(|byte| byte.is_ascii_digit()) => {
                output.push_str(&format!("%{}$@", &after[..end]));
                rest = &after[end + 1..];
            }
            _ => {
                output.push('{');
                rest = after;
            }
        }
    }
    output.push_str(rest);
    output
}

fn main() -> anyhow::Result<()> {
    let _ = rustls::crypto::ring::default_provider().install_default();
    let source = reqwest::blocking::get(SOURCE_URL)?.error_for_status()?.text()?;
    let config: Value = serde_json::from_str(&source)?;
    let push = config["push"].as_object().ok_or_else(|| anyhow::anyhow!("Telegram config has no push catalog"))?;
    let mut templates: Vec<(&String, &str)> = push
        .iter()
        .filter_map(|(key, value)| Some((key, value.as_str()?)))
        .filter(|(key, _)| {
            !key.is_empty()
                && key.bytes().all(|byte| byte.is_ascii_uppercase() || byte.is_ascii_digit() || byte == b'_')
                && !SERVICE_OR_UNSUPPORTED_KEYS.contains(&key.as_str())
        })
        .collect();
    templates.sort_by(|(left, _), (right, _)| collate(left, right));

    let backend = Path::new(env!("CARGO_MANIFEST_DIR"));
    let mut catalog = format!(
        "// Generated by src/bin/update-push-catalog.rs. Do not edit manually.\n// Source: {SOURCE_URL}\n\n\
         pub const TELEGRAM_PUSH_CATALOG_SHA256: &str = \"{}\";\n\n\
         /// Telegram's visible push keys with the number of arguments each takes, in catalog order.\n\
         pub const TELEGRAM_VISIBLE_PUSH_KEYS: &[(&str, u8)] = &[\n",
        sha256_hex(source.as_bytes())
    );
    for (key, _) in &templates {
        let arguments = config["push_arguments"][key.as_str()].as_object().map_or(0, |arguments| arguments.len());
        catalog.push_str(&format!("    (\"{key}\", {arguments}),\n"));
    }
    catalog.push_str("];\n");
    std::fs::write(backend.join("src/web_push/catalog.rs"), catalog)?;

    let mut strings = vec!["// Generated by Backend/src/bin/update-push-catalog.rs. Do not edit manually.".to_owned()];
    for (key, template) in &templates {
        strings.push(format!("{} = {};", serde_json::to_string(key)?, serde_json::to_string(&apple_format(template))?));
    }
    strings.push(String::new());
    std::fs::write(backend.join("../BetterTG/Resources/en.lproj/Localizable.strings"), strings.join("\n"))?;

    println!("Generated {} visible Telegram push localizations", templates.len());
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn converts_templates_to_apple_format() {
        assert_eq!(apple_format("{1} sent you {2}"), "%1$@ sent you %2$@");
        assert_eq!(apple_format("100% {1} {x}"), "100%% %1$@ {x}");
    }

    #[test]
    fn sorts_like_locale_compare() {
        let mut keys = vec!["MESSAGE_TEXT", "MESSAGE2", "MESSAGES", "MESSAGE"];
        keys.sort_by(|left, right| collate(left, right));
        assert_eq!(keys, ["MESSAGE", "MESSAGE_TEXT", "MESSAGE2", "MESSAGES"]);
    }
}
